function applyFade(samples, sr, fadeIn, fadeOut){
  if(!(sr>0)) return null; fadeIn=fadeIn||0; fadeOut=fadeOut||0;
  var n=samples.length, out=new Array(n);
  var inN=Math.floor(fadeIn*sr), outN=Math.floor(fadeOut*sr);
  for(var i=0;i<n;i++){ var g=1;
    if(i<inN) g*= (inN? i/inN : 1);
    if(outN && i>=n-outN) g*= (i-(n-outN))/outN;
    out[i]=Math.max(-1,Math.min(1,samples[i]*g));
  }
  return out;
}
var EXPORTS={applyFade:applyFade};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AudioFadeForgePure = EXPORTS; }
